"""SEC-14: `scripts/lock.py --upgrade X` drops X's old pin from the constraint
copy (a lock is a hard constraint), and leaves every other pin alone."""

from scripts import lock

LOCK = """\
# This file was autogenerated by uv via the following command:
#    python scripts/lock.py
cryptography==50.0.0 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
pydantic-settings==2.6.0 \\
    --hash=sha256:ccc
pytz==2024.1 \\
    --hash=sha256:ddd
"""


def test_without_drops_only_the_upgraded_pins_and_their_hashes(tmp_path):
    src = tmp_path / "requirements.lock"
    src.write_text(LOCK, encoding="utf-8")
    out = lock._without(src, ["Cryptography", "pydantic_settings"], tmp_path).read_text(encoding="utf-8")
    assert "cryptography" not in out and "aaa" not in out and "bbb" not in out
    assert "pydantic-settings" not in out and "ccc" not in out
    assert "pytz==2024.1 \\\n    --hash=sha256:ddd" in out
    assert out.startswith("# This file was autogenerated")
    assert src.read_text(encoding="utf-8") == LOCK  # the real lock is untouched
